            justify-content: center;
        }

        .stat-card {
            background: var(--bg-surface);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.2vw, 1.2rem) clamp(0.8rem, 1.5vw, 1.5rem);
            text-align: center;
            border-left: 3px solid var(--accent-amber);
            flex: 1;
            min-width: clamp(100px, 15vw, 160px);
            max-width: clamp(180px, 22vw, 220px);
        }

        .stat-card .stat-value {
            font-family: var(--font-display);
            font-size: var(--stat-size);
            font-weight: 700;
            color: var(--accent-amber);
            line-height: 1.1;
        }

        .stat-card .stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 2px;
        }

        .stat-card.teal { border-left-color: var(--accent-teal); }
        .stat-card.teal .stat-value { color: var(--accent-teal); }
        .stat-card.coral { border-left-color: var(--accent-coral); }
        .stat-card.coral .stat-value { color: var(--accent-coral); }
        .stat-card.blue { border-left-color: var(--accent-blue); }
        .stat-card.blue .stat-value { color: var(--accent-blue); }

        /* Treemap-style blocks */
        .treemap-grid {
            display: flex;
            flex-wrap: wrap;
            gap: clamp(3px, 0.4vw, 6px);
            flex: 1;
            min-height: 0;
            align-content: flex-start;
        }

        .treemap-block {
            border-radius: 4px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            padding: clamp(4px, 0.5vw, 8px);
            position: relative;
            overflow: hidden;
        }

        .treemap-block .tm-name {
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--text-primary);
            z-index: 1;
        }

        .treemap-block .tm-value {
            font-size: clamp(0.55rem, 0.8vw, 0.75rem);
            color: rgba(255,255,255,0.7);
            z-index: 1;
        }

        /* Diverging bar chart */
        .diverging-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(3px, 0.5vw, 5px);
            flex: 1;
            min-height: 0;
            justify-content: center;
        }

        .div-row {
            display: flex;
            align-items: center;
            gap: clamp(4px, 0.6vw, 8px);
        }

        .div-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: right;
            min-width: clamp(70px, 10vw, 120px);
            flex-shrink: 0;
        }

        .div-track {
            flex: 1;
            height: clamp(12px, 1.6vw, 20px);
            position: relative;
            background: rgba(255,255,255,0.03);
            border-radius: 2px;
        }

        .div-center-line {
            position: absolute;
            left: 50%;
            top: 0;
            bottom: 0;
            width: 1px;
            background: var(--text-muted);
        }

        .div-bar {
            position: absolute;
            top: 0;
            height: 100%;
            border-radius: 2px;
            transition: all 0.6s var(--ease-out-expo);
        }

        .div-bar.decline {
            background: var(--accent-teal);
            right: 50%;
        }

        .div-bar.growth {
            background: var(--accent-coral);
            left: 50%;
        }

        .div-value {
            font-size: clamp(0.5rem, 0.7vw, 0.65rem);
            color: var(--text-secondary);
            min-width: clamp(28px, 3vw, 40px);
            flex-shrink: 0;
        }

        /* Comparison blocks */
        .comparison-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.5rem, 1.5vw, 1.5rem);
            flex: 1;
            min-height: 0;
            align-content: center;
        }

        .comparison-col {
            background: var(--bg-surface);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.5vw, 1.2rem);
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
        }

        .comparison-col h3 {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 600;
            margin-bottom: 2px;
        }

        .comparison-col .comp-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: var(--body-size);
        }

        .comparison-col .comp-item .comp-val {
            font-weight: 600;
            font-family: var(--font-display);
            font-size: var(--h3-size);
        }

        /* Takeaway bullets */
        .takeaway-list {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.2vw, 1rem);
            flex: 1;
            justify-content: center;
        }

        .takeaway-item {
            display: flex;
            align-items: flex-start;
            gap: clamp(8px, 1vw, 14px);
            padding: clamp(0.5rem, 1vw, 0.8rem) clamp(0.7rem, 1.2vw, 1rem);
            background: var(--bg-surface);
            border-radius: 6px;
            border-left: 3px solid var(--accent-amber);
        }

        .takeaway-item .tk-num {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            font-weight: 700;
            color: var(--accent-amber);
            flex-shrink: 0;
            line-height: 1;
        }

        .takeaway-item .tk-text {
            font-size: var(--body-size);
            color: var(--text-primary);
            line-height: 1.4;
        }

        .takeaway-item .tk-text strong {
            color: var(--accent-amber);
        }

        /* Footnote / source line */
        .slide-footnote {
            font-size: clamp(0.5rem, 0.7vw, 0.65rem);
            color: var(--text-muted);
            padding: 0 var(--slide-padding) clamp(0.3rem, 0.5vw, 0.5rem);
            flex-shrink: 0;
        }

        /* Background patterns */
        .bg-grid {
            background-image:
                linear-gradient(rgba(255,255,255,0.015) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.015) 1px, transparent 1px);
            background-size: 40px 40px;
        }

        .bg-glow-warm {
            background:
                radial-gradient(ellipse at 10% 90%, rgba(232, 168, 56, 0.06) 0%, transparent 40%),
                var(--bg-primary);
        }

        .bg-glow-teal {
            background:
                radial-gradient(ellipse at 90% 10%, rgba(46, 196, 182, 0.05) 0%, transparent 40%),
                var(--bg-primary);
        }

        /* Slide number indicator */
        .slide-num {
            position: absolute;
            bottom: clamp(0.4rem, 0.8vw, 0.8rem);
            left: var(--slide-padding);
            font-size: clamp(0.5rem, 0.6vw, 0.6rem);
            color: var(--text-muted);
            font-weight: 500;
            letter-spacing: 0.1em;
        }

        /* Inline highlight */
        .hl-amber { color: var(--accent-amber); }
        .hl-teal { color: var(--accent-teal); }
        .hl-coral { color: var(--accent-coral); }
        .hl-blue { color: var(--accent-blue); }

        /* Chart axis label */
        .axis-label {
            font-size: clamp(0.5rem, 0.7vw, 0.65rem);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.08em;
        }
    </style>
</head>
<body>
    <!-- Progress bar -->
    <div class="progress-bar" id="progressBar"></div>

    <!-- Navigation dots -->
    <nav class="nav-dots" id="navDots"></nav>

    <!-- ==========================================
         SLIDE 1: TITLE
         ========================================== -->
    <section class="slide title-slide bg-grid" data-slide="0">
        <div class="slide-content" style="justify-content: center; align-items: center; text-align: center;">
            <div class="accent-line reveal"></div>
            <h1 class="reveal" style="transition-delay: 0.1s;">Global CO<sub>2</sub> Emissions</h1>
            <p class="subtitle reveal" style="transition-delay: 0.2s;">Who Emits, How Much, and What's Changing</p>
            <div class="accent-line reveal" style="transition-delay: 0.3s;"></div>
            <p class="reveal" style="transition-delay: 0.4s; font-size: var(--body-size); color: var(--text-secondary); max-width: min(70vw, 600px); line-height: 1.5; margin-top: var(--content-gap);">
                Fossil fuels &amp; industry &middot; 1750&ndash;2024
            </p>
            <p class="source-tag reveal" style="transition-delay: 0.5s; margin-top: var(--element-gap);">
                Data: <span>Global Carbon Budget 2025</span> via Our World in Data
            </p>
        </div>
        <div class="slide-num">01 / 09</div>
    </section>

    <!-- ==========================================
         SLIDE 2: GLOBAL EMISSIONS GROWTH
         ========================================== -->
    <section class="slide content-slide bg-glow-warm bg-grid" data-slide="1">
        <div class="slide-header">
            <h2 class="reveal">Global CO<sub>2</sub> Emissions Grew from <span class="hl-amber">6 Bt</span> in 1950 to Over <span class="hl-amber">35 Bt</span> Today</h2>
            <p class="slide-subtitle reveal" style="transition-delay: 0.1s;">Fossil fuel and industry emissions, 1750&ndash;2024. Growth has slowed but no peak yet.</p>
        </div>
        <div class="slide-body">
            <div class="chart-container reveal-scale" style="transition-delay: 0.2s;">
                <div class="axis-label" style="margin-bottom: 2px;">Billion tonnes CO<sub>2</sub>/year</div>
                <div class="area-chart" id="growthChart" style="border-bottom: 1px solid rgba(255,255,255,0.1); border-left: 1px solid rgba(255,255,255,0.1);">
                    <!-- Y-axis reference lines rendered via JS -->
                </div>
                <div style="display: flex; justify-content: space-between; margin-top: 2px;">
                    <span class="axis-label">1750</span>
                    <span class="axis-label">1850</span>
                    <span class="axis-label">1950</span>
                    <span class="axis-label">1990</span>
                    <span class="axis-label">2024</span>
                </div>
            </div>
            <div class="stat-row reveal" style="transition-delay: 0.35s; margin-top: var(--element-gap);">
                <div class="stat-card"><div class="stat-value">~0</div><div class="stat-label">1750 emissions</div></div>
                <div class="stat-card amber"><div class="stat-value">6 Bt</div><div class="stat-label">1950</div></div>
                <div class="stat-card"><div class="stat-value">20 Bt</div><div class="stat-label">1990</div></div>
                <div class="stat-card coral"><div class="stat-value">35+ Bt</div><div class="stat-label">2024</div></div>
            </div>
        </div>
        <div class="slide-footnote">Source: Global Carbon Budget 2025 via Our World in Data</div>
        <div class="slide-num">02 / 09</div>
    </section>

    <!-- ==========================================
         SLIDE 3: REGIONAL SHARE SHIFT
         ========================================== -->
    <section class="slide content-slide bg-glow-teal bg-grid" data-slide="2">
        <div class="slide-header">
            <h2 class="reveal">Europe and the US Fell from <span class="hl-amber">90%</span> of Emissions in 1900 to Under <span class="hl-teal">One-Third</span> Today</h2>
            <p class="slide-subtitle reveal" style="transition-delay: 0.1s;">Share of global CO<sub>2</sub> emissions by region, 1900&ndash;2024. Asia &mdash; led by China &mdash; now produces roughly half.</p>
        </div>
        <div class="slide-body">
            <div class="chart-container reveal-scale" style="transition-delay: 0.2s;">
                <!-- Stacked area representation via horizontal stacked bars -->
                <div style="display: flex; flex-direction: column; gap: clamp(8px, 1.5vw, 16px); flex: 1; justify-content: center;">
                    <!-- 1900 -->
                    <div class="reveal" style="transition-delay: 0.25s;">
                        <div style="display: flex; justify-content: space-between; margin-bottom: 3px;">
                            <span class="axis-label">1900</span>
                            <span class="axis-label" style="color: var(--accent-amber);">Europe + US: &gt;90%</span>
                        </div>
                        <div style="display: flex; height: clamp(18px, 2.5vw, 30px); border-radius: 3px; overflow: hidden;">
                            <div style="width: 70%; background: var(--accent-amber); display: flex; align-items: center; justify-content: center;"><span style="font-size: var(--small-size); font-weight: 600; color: #1a1a1a;">Europe 70%</span></div>
                            <div style="width: 22%; background: #d4913a; display: flex; align-items: center; justify-content: center;"><span style="font-size: var(--small-size); font-weight: 600; color: #1a1a1a;">US 22%</span></div>
                            <div style="width: 8%; background: var(--bg-surface); display: flex; align-items: center; justify-content: center;"><span style="font-size: clamp(0.45rem, 0.6vw, 0.55rem); color: var(--text-muted);">8%</span></div>
                        </div>
                    </div>
                    <!-- 1950 -->
                    <div class="reveal" style="transition-delay: 0.35s;">
                        <div style="display: flex; justify-content: space-between; margin-bottom: 3px;">
                            <span class="axis-label">1950</span>
                            <span class="axis-label">Europe + US: &gt;85%</span>
                        </div>
                        <div style="display: flex; height: clamp(18px, 2.5vw, 30px); border-radius: 3px; overflow: hidden;">
                            <div style="width: 50%; background: var(--accent-amber); display: flex; align-items: center; justify-content: center;"><span style="font-size: var(--small-size); font-weight: 600; color: #1a1a1a;">Europe 50%</span></div>
                            <div style="width: 35%; background: #d4913a; display: flex; align-items: center; justify-content: center;"><span style="font-size: var(--small-size); font-weight: 600; color: #1a1a1a;">US 35%</span></div>
                            <div style="width: 15%; background: var(--accent-coral); opacity: 0.6; display: flex; align-items: center; justify-content: center;"><span style="font-size: clamp(0.45rem, 0.6vw, 0.55rem);">Asia 8%</span></div>
                            <div style="width: 7%; background: var(--bg-surface);"></div>
                        </div>
                    </div>
                    <!-- 1990 -->
                    <div class="reveal" style="transition-delay: 0.45s;">
                        <div style="display: flex; justify-content: space-between; margin-bottom: 3px;">
                            <span class="axis-label">1990</span>
                            <span class="axis-label">Europe + US: ~50%</span>
                        </div>
                        <div style="display: flex; height: clamp(18px, 2.5vw, 30px); border-radius: 3px; overflow: hidden;">
                            <div style="width: 25%; background: var(--accent-amber); display: flex; align-items: center; justify-content: center;"><span style="font-size: var(--small-size); font-weight: 600; color: #1a1a1a;">Europe</span></div>
                            <div style="width: 23%; background: #d4913a; display: flex; align-items: center; justify-content: center;"><span style="font-size: var(--small-size); font-weight: 600; color: #1a1a1a;">US</span></div>
                            <div style="width: 28%; background: var(--accent-coral); display: flex; align-items: center; justify-content: center;"><span style="font-size: var(--small-size); font-weight: 600;">Asia 28%</span></div>
                            <div style="width: 24%; background: var(--bg-surface);"></div>
                        </div>
                    </div>
                    <!-- 2024 -->
                    <div class="reveal" style="transition-delay: 0.55s;">
                        <div style="display: flex; justify-content: space-between; margin-bottom: 3px;">
                            <span class="axis-label">2024</span>
                            <span class="axis-label" style="color: var(--accent-coral);">Asia: ~50%</span>
                        </div>
                        <div style="display: flex; height: clamp(18px, 2.5vw, 30px); border-radius: 3px; overflow: hidden;">
                            <div style="width: 12%; background: var(--accent-amber); display: flex; align-items: center; justify-content: center;"><span style="font-size: clamp(0.45rem, 0.6vw, 0.55rem); font-weight: 600; color: #1a1a1a;">EU</span></div>
                            <div style="width: 13%; background: #d4913a; display: flex; align-items: center; justify-content: center;"><span style="font-size: clamp(0.45rem, 0.6vw, 0.55rem); font-weight: 600; color: #1a1a1a;">US</span></div>
                            <div style="width: 50%; background: var(--accent-coral); display: flex; align-items: center; justify-content: center;"><span style="font-size: var(--small-size); font-weight: 600;">Asia ~50%</span></div>
                            <div style="width: 25%; background: var(--bg-surface); display: flex; align-items: center; justify-content: center;"><span style="font-size: clamp(0.45rem, 0.6vw, 0.55rem); color: var(--text-muted);">25%</span></div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="stat-row reveal" style="transition-delay: 0.6s; margin-top: var(--element-gap);">
                <div class="stat-card"><div class="stat-value">90%+</div><div class="stat-label">EU+US share, 1900</div></div>
                <div class="stat-card teal"><div class="stat-value">&lt;30%</div><div class="stat-label">EU+US share, 2024</div></div>
                <div class="stat-card coral"><div class="stat-value">~50%</div><div class="stat-label">Asia share, 2024</div></div>
            </div>
        </div>
        <div class="slide-footnote">Source: Global Carbon Budget 2025 via Our World in Data</div>
        <div class="slide-num">03 / 09</div>
    </section>

    <!-- ==========================================
         SLIDE 4: CHINA DOMINATES SHARE
         ========================================== -->
    <section class="slide content-slide bg-glow-warm bg-grid" data-slide="3">
        <div class="slide-header">
            <h2 class="reveal">China Now Emits More Than <span class="hl-coral">One-Quarter</span> of Global CO<sub>2</sub></h2>
            <p class="slide-subtitle reveal" style="transition-delay: 0.1s;">Country-level share of global CO<sub>2</sub> emissions, 2024. Top four emitters account for ~58%.</p>
        </div>
        <div class="slide-body">
            <div class="chart-container reveal-scale" style="transition-delay: 0.2s;">
                <div style="display: flex; gap: clamp(0.8rem, 2vw, 2rem); flex: 1; min-height: 0; align-items: stretch;">
