                    <div class="treemap-grid" style="flex: 2;">
                        <div class="treemap-block" style="width: 58%; height: 65%; background: var(--accent-coral);">
                            <span class="tm-name">China</span>
                            <span class="tm-value">~31%</span>
                        </div>
                        <div class="treemap-block" style="width: 38%; height: 35%; background: #d4913a;">
                            <span class="tm-name">US</span>
                            <span class="tm-value">~13%</span>
                        </div>
                        <div class="treemap-block" style="width: 38%; height: 28%; background: #b07830;">
                            <span class="tm-name">India</span>
                            <span class="tm-value">~8%</span>
                        </div>
