                            <span class="tm-value">~6%</span>
                        </div>
                        <div class="treemap-block" style="width: 28%; height: 32%; background: #8b6a3a;">
                            <span class="tm-name">Russia</span>
                            <span class="tm-value">~5%</span>
                        </div>
                    </div>
                    <!-- Side list -->
                    <div style="flex: 1; display: flex; flex-direction: column; justify-content: center; gap: clamp(4px, 0.6vw, 8px);">
                        <div class="reveal" style="transition-delay: 0.3s; display: flex; justify-content: space-between; padding: clamp(3px, 0.4vw, 6px) 0; border-bottom: 1px solid rgba(255,255,255,0.05);">
                            <span style="font-size: var(--body-size); color: var(--text-secondary);">Africa (total)</span>
                            <span style="font-size: var(--body-size); color: var(--text-primary); font-weight: 600;">3&ndash;4%</span>
                        </div>
                        <div class="reveal" style="transition-delay: 0.35s; display: flex; justify-content: space-between; padding: clamp(3px, 0.4vw, 6px) 0; border-bottom: 1px solid rgba(255,255,255,0.05);">
                            <span style="font-size: var(--body-size); color: var(--text-secondary);">S. America (total)</span>
                            <span style="font-size: var(--body-size); color: var(--text-primary); font-weight: 600;">3&ndash;4%</span>
                        </div>
                        <div class="reveal" style="transition-delay: 0.4s; display: flex; justify-content: space-between; padding: clamp(3px, 0.4vw, 6px) 0; border-bottom: 1px solid rgba(255,255,255,0.05);">
                            <span style="font-size: var(--body-size); color: var(--text-secondary);">Aviation &amp; shipping</span>
                            <span style="font-size: var(--body-size); color: var(--text-primary); font-weight: 600;">~3%</span>
                        </div>
                        <div class="reveal" style="transition-delay: 0.45s; padding: clamp(4px, 0.5vw, 8px); background: rgba(232,168,56,0.1); border-radius: 4px; margin-top: 4px;">
                            <span style="font-size: var(--small-size); color: var(--accent-amber);">Africa &amp; S. America each emit less than international aviation &amp; shipping combined</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
        <div class="slide-footnote">Source: Global Carbon Budget 2025 via Our World in Data</div>
        <div class="slide-num">04 / 09</div>
    </section>

    <!-- ==========================================
         SLIDE 5: PER CAPITA INEQUALITY (range)
         ========================================== -->
    <section class="slide content-slide bg-glow-warm bg-grid" data-slide="4">
        <div class="slide-header">
            <h2 class="reveal">Per Capita Emissions Range from <span class="hl-teal">0.1 t</span> in Chad to <span class="hl-coral">~14 t</span> in the US and Canada</h2>
            <p class="slide-subtitle reveal" style="transition-delay: 0.1s;">A <span class="hl-amber">150x gap</span> between the lowest and highest emitting nations. The average American emits in under two days what a person in Niger emits in a year.</p>
        </div>
        <div class="slide-body">
            <div class="chart-container reveal-scale" style="transition-delay: 0.2s;">
                <div class="hbar-chart">
                    <div class="hbar-row">
                        <span class="hbar-label">US / Canada</span>
                        <div class="hbar-track"><div class="hbar-fill" style="width: 100%; background: linear-gradient(90deg, var(--accent-coral), #c44a3a);"></div></div>
                        <span class="hbar-value" style="color: var(--accent-coral);">~14 t</span>
                    </div>
                    <div class="hbar-row">
                        <span class="hbar-label">China</span>
                        <div class="hbar-track"><div class="hbar-fill" style="width: 64%; background: linear-gradient(90deg, var(--accent-amber), #c48a28);"></div></div>
                        <span class="hbar-value" style="color: var(--accent-amber);">~9 t</span>
                    </div>
                    <div class="hbar-row">
                        <span class="hbar-label">S. Africa</span>
                        <div class="hbar-track"><div class="hbar-fill" style="width: 50%; background: #b09060;"></div></div>
                        <span class="hbar-value">~7 t</span>
                    </div>
                    <div class="hbar-row">
                        <span class="hbar-label">EU-27</span>
                        <div class="hbar-track"><div class="hbar-fill" style="width: 43%; background: var(--accent-teal);"></div></div>
                        <span class="hbar-value" style="color: var(--accent-teal);">~6 t</span>
                    </div>
                    <div class="hbar-row">
                        <span class="hbar-label" style="font-weight: 600; color: var(--text-primary);">World avg</span>
